constexpr size_t N = 4, MASK = N - 1;
int buf[N]; size_t head = 0, tail = 0;
bool full() { return
  (tail & MASK) + 1 == (head & MASK); }
bool empty() { return
  (tail & MASK) == (head & MASK); }
bool push(int v) {
  if (full()) return false;
  buf[tail++ & MASK] = v; return true; }
int n = 0;
for (int i = 1; i <= 4; ++i) n += push(i);
std::cout << "accepted=" << n << " empty="
  << std::boolalpha << empty();

